/* Real search panel, shared decoder/matcher and Windows/native Linux workers. */
#define wWinMain content_unused_entrypoint
#include "../app/fpcontent.c"
#undef wWinMain
#include "../app/textutil.h"
static int passed,failed;static wchar_t fixture[32768];
#define CHECK(label,condition) do{if(condition){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static cf_options opts(const wchar_t *query,const wchar_t *pattern,uint32_t flags){cf_options o={.flags=flags};for(uint32_t i=0;i<CF_QUERY&&query[i];i++)o.query[i]=(uint16_t)query[i];for(uint32_t i=0;i<CF_QUERY&&pattern[i];i++)o.pattern[i]=(uint16_t)pattern[i];return o;}
static int receive(void *p,const cf_record *r,const wchar_t *relative){return content_model_add(p,r,relative);}
static void path(wchar_t out[32768],const wchar_t *name){swprintf(out,32768,L"%ls\\%ls",fixture,name);}
static void write_fixture(const wchar_t *name,const void *data,DWORD n){wchar_t p[32768];path(p,name);HANDLE h=CreateFileW(p,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);CHECK("owned fixture created",h!=INVALID_HANDLE_VALUE);if(h!=INVALID_HANDLE_VALUE){DWORD wrote;CHECK("fixture bytes written",WriteFile(h,data,n,&wrote,NULL)&&wrote==n);CloseHandle(h);}}
static void setup(void){wchar_t temp[32768],p[32768];GetTempPathW(32768,temp);swprintf(fixture,32768,L"%lsopenpilot-content-%lu-%llu",temp,(unsigned long)GetCurrentProcessId(),(unsigned long long)GetTickCount64());CHECK("fresh fixture root",CreateDirectoryW(fixture,NULL));path(p,L"nested");CHECK("nested folder created",CreateDirectoryW(p,NULL));const char *notes="intro\r\nAlpha beta alpha\r\nalphabet alpha_ ALPHA\r\nunicode café 😀\r\n";write_fixture(L"notes.txt",notes,(DWORD)strlen(notes));write_fixture(L"nested\\code.py","alpha\nfinal alpha\n",18);write_fixture(L"readme.custom","some alpha content",18);const uint16_t unicode[]={0xfeff,'o','n','e','\r','\n','A','L','P','H','A',' ','b','e','t','a','\r','\n'};write_fixture(L"utf16.txt",unicode,sizeof unicode);const unsigned char binary[]={0,1,0,0,255,4};write_fixture(L"binary.bin",binary,sizeof binary);path(p,L"large.bin");HANDLE h=CreateFileW(p,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);CHECK("large fixture opened",h!=INVALID_HANDLE_VALUE);if(h!=INVALID_HANDLE_VALUE){LARGE_INTEGER end={.QuadPart=CF_FILE_BYTES+1};CHECK("large fixture bounded length",SetFilePointerEx(h,end,NULL,FILE_BEGIN)&&SetEndOfFile(h));CloseHandle(h);}path(p,L"loop");CHECK("link fixture created",CreateSymbolicLinkW(p,fixture,3)||CreateSymbolicLinkW(p,fixture,1));}
static void cleanup(void){const wchar_t *files[]={L"notes.txt",L"nested\\code.py",L"readme.custom",L"utf16.txt",L"binary.bin",L"large.bin"};wchar_t p[32768];for(unsigned i=0;i<6;i++){path(p,files[i]);DeleteFileW(p);}path(p,L"loop");RemoveDirectoryW(p);path(p,L"nested");RemoveDirectoryW(p);RemoveDirectoryW(fixture);}
static void test_content_matcher_encoding_positions_and_limits(void){cf_options o=opts(L"alpha",L"*",0);cf_hit *hits=NULL;uint32_t count=0;int more=0;const unsigned char text[]="intro\r\nAlpha beta alpha\r\nalphabet alpha_ ALPHA";CHECK("literal matcher decodes text",content_match_bytes(text,sizeof text-1,&o,100,&hits,&count,&more)==1);CHECK("all occurrences have normalized line/column",count==5&&!more&&hits[0].line==2&&hits[0].column==1&&hits[1].line==2&&hits[1].column==12);CHECK("actual case-preserved match text retained",hits&&hits[0].matched[0]=='A'&&hits[1].matched[0]=='a');free(hits);o.flags=CF_CASE|CF_WORD;content_match_bytes(text,sizeof text-1,&o,100,&hits,&count,&more);CHECK("whole word excludes prefixes and underscore words",count==1&&hits[0].column==12);free(hits);o=opts(L"aa",L"*",0);content_match_bytes((void*)"aaaa",4,&o,2,&hits,&count,&more);CHECK("overlapping literal matches stop at the result bound",count==2&&more);free(hits);o=opts(L"café",L"*",0);const uint16_t utf16[]={0xfeff,'x','\r','\n','c','a','f',0xe9};content_match_bytes((void*)utf16,sizeof utf16,&o,10,&hits,&count,&more);CHECK("BOM UTF-16 uses the preview decoder and line numbering",count==1&&hits[0].line==2&&hits[0].encoding==TEXT_UTF16LE);free(hits);unsigned char binary[]={0,0,0,1,2,0};CHECK("binary input is excluded",content_match_bytes(binary,sizeof binary,&o,10,&hits,&count,&more)==0);CHECK("empty and multiline queries refused",!content_options_valid(&(cf_options){0})&&!content_options_valid(&(cf_options){.query={'a','\n',0}}));CHECK("filename wildcard lists work",content_name_matches(L"FILE.PY",(uint16_t[]){'*','.','t','x','t',';','*','.','p','y',0})&&!content_name_matches(L"file.bin",(uint16_t[]){'*','.','p','y',0}));}
static void test_content_windows_filters_recursion_and_partial(void){cf_model m={0};cf_options o=opts(L"alpha",L"*.txt;*.py;*.custom",CF_RECURSE);CHECK("Windows content scan completes",!content_scan(fixture,&o,0,0,NULL,receive,&m)&&m.summary.state==CF_COMPLETE);CHECK("matching files and all occurrences retained",m.count==9&&m.summary.files==4&&m.summary.matches==9);int unicode=0,custom=0;for(uint32_t i=0;i<m.count;i++){if(!wcscmp(m.rows[i].path,L"utf16.txt"))unicode=m.rows[i].hit.line==2&&m.rows[i].hit.column==1;if(!wcscmp(m.rows[i].path,L"readme.custom"))custom=1;}CHECK("UTF-16 and unknown-extension text are searchable",unicode&&custom);content_model_free(&m);o.flags=0;content_scan(fixture,&o,0,0,NULL,receive,&m);CHECK("subfolder toggle changes traversal scope",m.count==7&&m.summary.state==CF_COMPLETE);content_model_free(&m);o=opts(L"alpha",L"*.py",CF_RECURSE|CF_CASE|CF_WORD);content_scan(fixture,&o,0,0,NULL,receive,&m);CHECK("file pattern narrows reads to the selected type",m.count==2&&m.summary.files==1);content_model_free(&m);o=opts(L"alpha",L"*",CF_RECURSE);content_scan(fixture,&o,0,0,NULL,receive,&m);CHECK("binary and oversized exclusions are reported explicitly",m.summary.binary==1&&m.summary.large==1&&m.summary.state==CF_PARTIAL);content_model_free(&m);o=opts(L"absent",L"*.txt",CF_RECURSE);content_scan(fixture,&o,0,0,NULL,receive,&m);CHECK("zero matches is a complete successful search",m.count==0&&m.summary.state==CF_COMPLETE);content_model_free(&m);}
typedef struct cancelled {cf_model m;HANDLE event;} cancelled;
static int cancel_on_match(void *p,const cf_record *r,const wchar_t *relative){cancelled *c=p;int ok=content_model_add(&c->m,r,relative);if(r->type==CF_MATCH)SetEvent(c->event);return ok;}
static void test_content_stop_errors_and_path_scope(void){cf_options o=opts(L"alpha",L"*.txt;*.py",CF_RECURSE);cancelled c={.event=CreateEventW(NULL,TRUE,FALSE,NULL)};content_scan(fixture,&o,0,0,c.event,cancel_on_match,&c);CHECK("in-flight Stop retains partial results",c.m.count==1&&c.m.summary.state==CF_STOPPED);CloseHandle(c.event);content_model_free(&c.m);cf_model m={0};wchar_t p[32768];path(p,L"nested");HANDLE h=CreateFileW(p,GENERIC_READ,0,NULL,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,NULL);CHECK("private unreadable subtree fixture",h!=INVALID_HANDLE_VALUE);content_scan(fixture,&o,0,0,NULL,receive,&m);CHECK("unreadable subtrees keep readable hits with partial status",m.count==6&&m.summary.errors==1&&m.summary.state==CF_PARTIAL);content_model_free(&m);if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);content_scan(L"\\\\wsl.localhost\\Ubuntu\\tmp",&o,0,0,NULL,receive,&m);CHECK("disabled WSL reports unavailable without provider fallback",m.summary.state==CF_PARTIAL&&m.summary.error==ERROR_NOT_SUPPORTED);content_model_free(&m);CHECK("logical result paths reject roots and traversal",content_relative_safe(L"nested\\file.txt")&&!content_relative_safe(L"..\\escape")&&!content_relative_safe(L"C:\\escape")&&!content_relative_safe(L"a\\..\\escape"));}
static void test_content_panel_query_generation_and_hidden_results(void){InitializeCriticalSection(&A.lock);A.dpi=96;A.shown=1;A.focus=1;A.flags=CF_RECURSE;A.selected=UINT32_MAX;wcscpy(A.pattern,L"*.txt;*.py;*.custom");A.caret[1]=(int)wcslen(A.pattern);A.out=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);A.cancel=CreateEventW(NULL,TRUE,FALSE,NULL);A.hwnd=CreateWindowExW(0,L"STATIC",L"Owned content acceptance",WS_POPUP,0,0,0,0,NULL,NULL,GetModuleHandleW(NULL),NULL);fonts();HANDLE section=CreateFileMappingW(INVALID_HANDLE_VALUE,NULL,PAGE_READWRITE,0,560*850*8,NULL);CHECK("real content panel maps its pixels",map(section,560,850));content_open request={.session=101};queue_root(fixture,&request);CHECK("opening captures root without starting content I/O",A.root&&!wcscmp(A.root,fixture)&&!A.thread&&!A.model.count);const wchar_t *query=L"alpha";for(int i=0;query[i];i++)input(&(panelp_input){.msg=WM_CHAR,.wparam=query[i]});input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_RETURN});uint64_t until=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<until){Sleep(5);tick();}CHECK("explicit Start populates actual matching rows",A.model.count==9&&!A.thread&&A.model.summary.state==CF_COMPLETE);A.request.wsl=1;A.run_wsl=1;struct {panelp_head h;uint32_t enabled;} policy={{PANELP_CONTENT_WSL_POLICY,4},0};on_host((msg*)&policy);CHECK("policy intake preserves completed Windows results and captured worker policy",!A.request.wsl&&!A.pending_request.wsl&&A.run_wsl==1&&A.model.count==9);begin();uint64_t policy_until=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<policy_until){Sleep(5);tick();}CHECK("next Windows worker captures disabled WSL policy",!A.thread&&!A.run_wsl&&A.model.count==9);uint32_t generation=A.generation;A.focus=1;input(&(panelp_input){.msg=WM_CHAR,.wparam='z'});CHECK("editing invalidates the old result authority",A.stale&&A.generation!=generation&&A.model.count==9);input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_BACK});begin();until=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<until){Sleep(5);tick();}CHECK("restarting replaces stale rows rather than appending",!A.stale&&A.model.count==9);A.shown=0;uint32_t before=A.generation;tick();CHECK("hidden results retain their query generation",A.model.count==9&&A.generation==before);A.shown=1;A.waiting=0;A.pending=0;int bank=A.next;tick();CHECK("retained idle results do not send redundant frames",A.next==bank&&!A.waiting);A.shown=1;A.selected=0;A.focus=0;paint();GdiFlush();wchar_t shot[32768];if(GetEnvironmentVariableW(L"OPENPILOT_CONTENT_SCREENSHOT",shot,32768)){BITMAPINFOHEADER bi={sizeof bi,A.w,-A.h,1,32,BI_RGB};BITMAPFILEHEADER fh={.bfType=0x4d42,.bfSize=(DWORD)(sizeof fh+sizeof bi+A.w*A.h*4),.bfOffBits=sizeof fh+sizeof bi};HANDLE f=CreateFileW(shot,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);if(f!=INVALID_HANDLE_VALUE){io(f,&fh,sizeof fh,1);io(f,&bi,sizeof bi,1);io(f,A.pixels,A.w*A.h*4,1);CloseHandle(f);}}content_model_free(&A.model);free(A.root);free(A.pending_root);CloseHandle(A.out);CloseHandle(A.cancel);if(A.shared)UnmapViewOfFile(A.shared);CloseHandle(A.section);DestroyWindow(A.hwnd);DeleteCriticalSection(&A.lock);memset(&A,0,sizeof A);}
static void test_content_native_linux_search_and_partial(void){wchar_t root[32768];DWORD n=GetEnvironmentVariableW(L"OPENPILOT_CONTENT_WSL_FIXTURE",root,32768);CHECK("owned native Linux fixture supplied",n>0&&n<32768);if(!n||n>=32768)return;cf_options o=opts(L"alpha",L"*.txt;*.py;*.custom",CF_RECURSE);cf_model m={0};DWORD error=content_scan(root,&o,1,0,NULL,receive,&m);CHECK("Windows helper uses native Linux search and shared positions",!error&&m.summary.state==CF_COMPLETE&&m.count==10);int literal=0,utf16=0;for(uint32_t i=0;i<m.count;i++){if(!wcscmp(m.rows[i].path,L"a\uf03ab.txt"))literal=1;if(!wcscmp(m.rows[i].path,L"utf16.txt"))utf16=m.rows[i].hit.line==2;}CHECK("native literal names and UTF-16 survive result transport",literal&&utf16);content_model_free(&m);n=GetEnvironmentVariableW(L"OPENPILOT_CONTENT_WSL_PARTIAL",root,32768);CHECK("owned Linux denied fixture supplied",n>0&&n<32768);if(n&&n<32768){content_scan(root,&o,1,0,NULL,receive,&m);CHECK("native unreadable subtree is partial with readable matches",m.summary.state==CF_PARTIAL&&m.summary.errors==1&&m.count==1);content_model_free(&m);}}
int wmain(void){setlocale(LC_CTYPE,".UTF8");SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);setup();test_content_matcher_encoding_positions_and_limits();test_content_windows_filters_recursion_and_partial();test_content_stop_errors_and_path_scope();test_content_panel_query_generation_and_hidden_results();test_content_native_linux_search_and_partial();cleanup();printf("%d passed, %d failed; 5 content selectors\n",passed,failed);return failed?1:0;}
